mapper.select:
SELECT 
  FROM WALK_RECORDS
 WHERE USERNAME  = #{username}
   AND STOP_NAME <=> #{stopName}
 ORDER BY ID DESC

SELECT 
  FROM WALK_RECORDS
 WHERE USERNAME    = #{username}
   AND EXCLUDED_YN = 'N'
   AND TIMESTAMPDIFF(SECOND, STARTED_AT, ARRIVED_AT) BETWEEN #{minSec} AND #{maxSec}
 ORDER BY TIMESTAMPDIFF(SECOND, STARTED_AT, ARRIVED_AT)

mapper.update:
UPDATE WALK_RECORDS
   SET EXCLUDED_YN = #{excludedYn}
 WHERE ID       = #{id}
   AND USERNAME = #{username}

mapper.delete:
DELETE FROM WALK_RECORDS
 WHERE ID       = #{id}
   AND USERNAME = #{username}
